import { existsSync } from "node:fs";
import { join } from "node:path";
import { topoSort, type Manifests } from "./graph.ts";
import { BLOCKS_DIR, type BlockManifest } from "./manifest.ts";

export const GEN_DIR = "src/gen";

const HEADER = "// Generated by `cf-saas-blocks sync` from each block's block.json. Do not edit.\n";

/** Files a block may provide; each one is gathered into a generated file under src/gen. */
export const contributions = ["layer", "errors", "events", "nav", "auth-plugins", "workflows", "viewer"] as const;
export type Contribution = (typeof contributions)[number];

const camel = (name: string) => name.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());

const has = (root: string, block: string, file: Contribution) =>
  existsSync(join(root, BLOCKS_DIR, block, `${file}.ts`));

const importPath = (block: string, file: Contribution) => `../blocks/${block}/${file}.ts`;

const layersFile = (root: string, order: ReadonlyArray<string>) => {
  const withLayer = order.filter((b) => has(root, b, "layer"));
  const imports = withLayer.map((b) => `import { layer as ${camel(b)} } from "${importPath(b, "layer")}";`);
  const [first, ...rest] = withLayer.map(camel);
  const body = first
    ? rest.reduce((acc, next) => `${next}.pipe(Layer.provideMerge(${acc}))`, first)
    : "Layer.empty";
  const effectImport = body.includes("Layer.") ? 'import { Layer } from "effect";\n' : "";
  return `${HEADER}${effectImport}${imports.join("\n")}\n\n/** Every enabled block's services, each provided with the blocks it requires. */\nexport const BlocksLayer = ${body};\n`;
};

const errorsFile = (root: string, order: ReadonlyArray<string>) => {
  const blocks = order.filter((b) => has(root, b, "errors"));
  const imports = blocks.map((b) => `import type * as ${camel(b)}Errors from "${importPath(b, "errors")}";`);
  const values = blocks.map(
    (b) => `import { errorStatus as ${camel(b)}ErrorStatus } from "${importPath(b, "errors")}";`,
  );
  const type = blocks.length ? blocks.map((b) => `${camel(b)}Errors.Errors`).join(" | ") : "never";
  const status = blocks.map((b) => `  ...${camel(b)}ErrorStatus,`).join("\n");
  return `${HEADER}${[...imports, ...values].join("\n")}\n\nexport type BlockError = ${type};\n\nexport const blockErrorStatus = {\n${status}\n} as const;\n`;
};

const listFile = (
  root: string,
  order: ReadonlyArray<string>,
  file: Contribution,
  exported: string,
  name: string,
  doc: string,
) => {
  const blocks = order.filter((b) => has(root, b, file));
  const imports = blocks.map((b) => `import { ${exported} as ${camel(b)} } from "${importPath(b, file)}";`);
  const items = blocks.map((b) => `...${camel(b)}`).join(", ");
  return `${HEADER}${imports.join("\n")}\n\n/** ${doc} */\nexport const ${name} = [${items}] as const;\n`;
};

const authPluginsFile = (root: string, order: ReadonlyArray<string>) => {
  const blocks = order.filter((b) => has(root, b, "auth-plugins"));
  const imports = blocks.map(
    (b) => `import { authPlugins as ${camel(b)} } from "${importPath(b, "auth-plugins")}";`,
  );
  return `${HEADER}${imports.join("\n")}\n\n/** Better Auth plugin factories from every block that extends auth. */\nexport const blockAuthPlugins = [${blocks.map(camel).join(", ")}] as const;\n`;
};

const workflowsFile = (manifests: Manifests, order: ReadonlyArray<string>) => {
  const lines = order.flatMap((b) =>
    (manifests.get(b)?.bindings ?? [])
      .filter((x) => x.type === "workflow")
      .map((x) => `export { ${x.class_name} } from "${importPath(b, "workflows")}";`),
  );
  return `${HEADER}${lines.join("\n")}${lines.length ? "\n" : "export {};\n"}`;
};

const envFile = (manifests: Manifests, order: ReadonlyArray<string>) => {
  const all = ["core", ...order].map((b) => manifests.get(b)).filter((m): m is BlockManifest => !!m);
  const secrets = all.flatMap((m) => Object.keys(m.secrets ?? {}));
  const required = all.flatMap((m) =>
    Object.entries({ ...m.vars, ...m.secrets })
      .filter(([, spec]) => spec.required)
      .map(([key]) => key),
  );
  const secretType = secrets.length ? secrets.map((s) => `"${s}"`).join(" | ") : "never";
  return `${HEADER}\n/** Secrets are set with \`wrangler secret put\`, so \`wrangler types\` cannot see them. */\nexport type SecretName = ${secretType};\nexport type BlockSecrets = Partial<Record<SecretName, string>>;\n\n/** Settings a deploy needs before it can serve traffic. \`setup --check\` reads the same list. */\nexport const requiredSettings = ${JSON.stringify(required)} as const;\n`;
};

export const enabledOrder = (manifests: Manifests): ReadonlyArray<string> =>
  topoSort(
    manifests,
    [...manifests.keys()].filter((name) => name !== "core"),
  );

/** Every generated file, keyed by its path from the project root. */
export const generateFiles = (root: string, manifests: Manifests): ReadonlyMap<string, string> => {
  const order = enabledOrder(manifests);
  return new Map([
    [`${GEN_DIR}/layers.ts`, layersFile(root, order)],
    [`${GEN_DIR}/errors.ts`, errorsFile(root, order)],
    [
      `${GEN_DIR}/events.ts`,
      listFile(root, order, "events", "events", "blockEvents", "Analytics events every enabled block adds to the catalog."),
    ],
    [`${GEN_DIR}/nav.ts`, listFile(root, order, "nav", "nav", "blockNav", "Navigation entries from every enabled block.")],
    [`${GEN_DIR}/auth-plugins.ts`, authPluginsFile(root, order)],
    [`${GEN_DIR}/workflows.ts`, workflowsFile(manifests, order)],
    [
      `${GEN_DIR}/viewer.ts`,
      listFile(root, order, "viewer", "viewer", "blockViewers", "Who is looking at the page; the first block that knows wins."),
    ],
    [`${GEN_DIR}/env.ts`, envFile(manifests, order)],
  ]);
};

/** `.dev.vars.example`: every var and secret, with what it is for. */
export const devVarsExample = (manifests: Manifests): string => {
  const order = ["core", ...enabledOrder(manifests)];
  const sections = order.flatMap((name) => {
    const m = manifests.get(name);
    if (!m) return [];
    const entries = Object.entries({ ...m.vars, ...m.secrets });
    if (!entries.length) return [];
    const lines = entries.map(([key, spec]) => {
      const need = spec.required ? "required" : "optional";
      const help = spec.help ? ` See ${spec.help}` : "";
      return `# ${spec.description} (${need}).${help}\n${key}=${spec.default ?? ""}`;
    });
    return [`# --- ${m.title} ---\n${lines.join("\n")}`];
  });
  return `# Copy to .dev.vars for local development. Generated by \`cf-saas-blocks sync\`.\n\n${sections.join("\n\n")}\n`;
};
